<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function ep_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())ep_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))ep_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];$leaders=['director','sub_director','headteacher'];$canView=$role==='hr'||in_array($role,$leaders,true);if(!$canView)ep_json(403,['ok'=>false,'message'=>'Your role cannot access staff profiles.']);$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);if(!$school)ep_json(422,['ok'=>false,'message'=>'Choose a school.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())ep_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$staffRoles="'admin','director','sub_director','headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'";
if($_SERVER['REQUEST_METHOD']==='GET'){$q=$db->prepare("SELECT u.id user_id,u.name,u.role,u.status,p.id profile_id,p.employee_number,p.job_title,p.department,p.employment_type,p.updated_at FROM school_memberships m JOIN users u ON u.id=m.user_id LEFT JOIN employee_profiles p ON p.user_id=u.id AND p.school_id=m.school_id WHERE m.school_id=? AND u.role IN ($staffRoles) ORDER BY u.status,u.name");$q->execute([$school]);ep_json(200,['ok'=>true,'data'=>['staff'=>$q->fetchAll(),'can_edit'=>$role==='hr']]);}
if($_SERVER['REQUEST_METHOD']!=='POST'||$role!=='hr')ep_json(403,['ok'=>false,'message'=>'Only the school HR role can edit staff profiles.']);verify_csrf();$staffId=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);$number=trim((string)($_POST['employee_number']??''));$title=trim((string)($_POST['job_title']??''));$department=trim((string)($_POST['department']??''));$type=trim((string)($_POST['employment_type']??''));$types=['','full_time','part_time','casual','volunteer','contract'];if(!$staffId||mb_strlen($number)>60||mb_strlen($title)>140||mb_strlen($department)>120||!in_array($type,$types,true))ep_json(422,['ok'=>false,'message'=>'Check the employee and profile field lengths.']);$q=$db->prepare("SELECT u.id FROM school_memberships m JOIN users u ON u.id=m.user_id WHERE m.school_id=? AND u.id=? AND u.role IN ($staffRoles)");$q->execute([$school,$staffId]);if(!$q->fetchColumn())ep_json(403,['ok'=>false,'message'=>'Choose a staff account linked to this school.']);try{$db->beginTransaction();$q=$db->prepare('SELECT id FROM employee_profiles WHERE school_id=? AND user_id=? FOR UPDATE');$q->execute([$school,$staffId]);$profileId=$q->fetchColumn();if($profileId){$q=$db->prepare('UPDATE employee_profiles SET employee_number=?,job_title=?,department=?,employment_type=?,updated_by=? WHERE id=? AND school_id=?');$q->execute([$number?:null,$title?:null,$department?:null,$type?:null,$uid,$profileId,$school]);$action='update';$entity=(int)$profileId;}else{$q=$db->prepare('INSERT INTO employee_profiles(school_id,user_id,employee_number,job_title,department,employment_type,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$school,$staffId,$number?:null,$title?:null,$department?:null,$type?:null,$uid,$uid]);$action='create';$entity=(int)$db->lastInsertId();}$q=$db->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,'employee_profile',?,?)");$q->execute([$uid,$action,$entity,json_encode(['school_id'=>$school,'user_id'=>$staffId],JSON_THROW_ON_ERROR)]);$db->commit();ep_json(200,['ok'=>true,'message'=>'Employee profile saved.']);}catch(PDOException $e){if($db->inTransaction())$db->rollBack();$duplicate=$e->getCode()==='23000';ep_json($duplicate?409:500,['ok'=>false,'message'=>$duplicate?'That employee number is already used at this school.':'Employee profile could not be saved.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();ep_json(500,['ok'=>false,'message'=>'Employee profile could not be saved.']);}
